#!/usr/bin/env python3
"""Lossless file compression, using only the Python standard library."""
import bz2
import sys
from pathlib import Path


def compress(data):
    return bz2.compress(data, compresslevel=9)


def decompress(data):
    return bz2.decompress(data)


def main():
    args = sys.argv[1:]
    decoding = bool(args and args[0] == '--decompress')
    if decoding:
        args = args[1:]
    if len(args) != 2:
        raise SystemExit('usage: compress.py [--decompress] INPUT OUTPUT')
    data = Path(args[0]).read_bytes()
    Path(args[1]).write_bytes(decompress(data) if decoding else compress(data))


if __name__ == '__main__':
    main()

